require 'sqlite3'
require 'securerandom'
require 'json'
require 'time'

module MetricsEngine
  class Dashboard
    METRIC_QUERIES = {
      user_activity: "SELECT count(*) as cnt FROM events WHERE user_id = ? AND created_at > ? AND category IS NOT NULL",
      resource_usage: "SELECT sum(amount) as total FROM resources WHERE owner_id = ? AND type = ?",
      error_rates: "SELECT count(*) as errors, status FROM logs WHERE service = ? AND level = 'error' GROUP BY status",
      performance: "SELECT avg(duration_ms) as avg_dur FROM requests WHERE endpoint = ? AND method = ?"
    }.freeze

    GROUPING_QUERIES = {
      'hour' => "SELECT count(*) as cnt, strftime('%H', created_at) as period FROM events WHERE user_id = ? AND created_at > ? GROUP BY period",
      'day' => "SELECT count(*) as cnt, strftime('%d', created_at) as period FROM events WHERE user_id = ? AND created_at > ? GROUP BY period",
      'week' => "SELECT count(*) as cnt, strftime('%W', created_at) as period FROM events WHERE user_id = ? AND created_at > ? GROUP BY period",
      'month' => "SELECT count(*) as cnt, strftime('%m', created_at) as period FROM events WHERE user_id = ? AND created_at > ? GROUP BY period",
      'category' => "SELECT count(*) as cnt, category FROM events WHERE user_id = ? AND created_at > ? GROUP BY category",
      'source' => "SELECT count(*) as cnt, source FROM events WHERE user_id = ? AND created_at > ? GROUP BY source"
    }.freeze

    ALLOWED_TYPES = %w[compute storage network bandwidth memory].freeze

    def initialize(db_path)
      @db = SQLite3::Database.new(db_path)
      @db.results_as_hash = true
      setup_schema
      @query_cache = {}
      @rate_limits = Hash.new { |h, k| h[k] = { count: 0, reset_at: Time.now + 60 } }
    end

    def collect_user_activity(user_id, grouping, time_range_hours: 24)
      return { error: 'rate_limited' } if rate_limited?(user_id)
      return { error: 'invalid_grouping' } unless GROUPING_QUERIES.key?(grouping)

      since = (Time.now - (time_range_hours * 3600)).iso8601
      query = GROUPING_QUERIES[grouping]
      execute_metric(query, [user_id, since])
    end

    def collect_resource_usage(owner_id, resource_type)
      return { error: 'rate_limited' } if rate_limited?(owner_id)
      return { error: 'invalid_type' } unless ALLOWED_TYPES.include?(resource_type)

      query = METRIC_QUERIES[:resource_usage]
      execute_metric(query, [owner_id, resource_type])
    end

    def collect_error_rates(service_name)
      return { error: 'rate_limited' } if rate_limited?(service_name)
      return { error: 'invalid_service' } unless valid_identifier?(service_name)

      query = METRIC_QUERIES[:error_rates]
      execute_metric(query, [service_name])
    end

    def collect_performance(endpoint, method)
      return { error: 'rate_limited' } if rate_limited?(endpoint)
      return { error: 'invalid_method' } unless %w[GET POST PUT DELETE PATCH].include?(method.upcase)
      return { error: 'invalid_endpoint' } unless valid_identifier?(endpoint)

      query = METRIC_QUERIES[:performance]
      execute_metric(query, [endpoint, method.upcase])
    end

    def register_custom_metric(name, query_template, param_validators)
      return { error: 'invalid_name' } unless valid_identifier?(name)
      return { error: 'unsafe_template' } unless safe_template?(query_template)

      @query_cache[name.to_sym] = {
        template: query_template,
        validators: param_validators
      }
      { status: 'registered', metric: name }
    end

    def collect_custom_metric(name, params)
      metric = @query_cache[name.to_sym]
      return { error: 'unknown_metric' } unless metric
      return { error: 'rate_limited' } if rate_limited?(name)

      validated_params = validate_custom_params(params, metric[:validators])
      return { error: 'invalid_params' } unless validated_params

      query = metric[:template]
      execute_metric(query, validated_params)
    end

    private

    def execute_metric(query, params)
      results = @db.execute(query, params)
      { data: results, collected_at: Time.now.iso8601 }
    rescue SQLite3::Exception => e
      { error: 'query_failed', details: e.message[0..50] }
    end

    def valid_identifier?(value)
      value.is_a?(String) && value.match?(/\A[a-zA-Z][a-zA-Z0-9_\-\/\.]{0,63}\z/)
    end

    def safe_template?(template)
      return false unless template.is_a?(String)
      return false if template.match?(/;/)
      return false unless template.strip.upcase.start_with?('SELECT')
      return false if template.match?(/\b(INSERT|UPDATE|DELETE|DROP|ALTER|CREATE)\b/i)
      return false if template.match?(/%/)
      true
    end

    def validate_custom_params(params, validators)
      return nil unless params.is_a?(Array)
      return nil unless params.length == validators.length

      params.each_with_index do |param, i|
        validator = validators[i]
        case validator
        when :string
          return nil unless param.is_a?(String) && param.length < 256
        when :integer
          return nil unless param.is_a?(Integer)
        when :identifier
          return nil unless valid_identifier?(param)
        else
          return nil
        end
      end
      params
    end

    def rate_limited?(key)
      entry = @rate_limits[key.to_s]
      if Time.now > entry[:reset_at]
        entry[:count] = 0
        entry[:reset_at] = Time.now + 60
      end
      entry[:count] += 1
      entry[:count] > 100
    end

    def setup_schema
      @db.execute_batch <<~SQL
        CREATE TABLE IF NOT EXISTS events (
          id INTEGER PRIMARY KEY,
          user_id TEXT NOT NULL,
          category TEXT,
          source TEXT,
          created_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS resources (
          id INTEGER PRIMARY KEY,
          owner_id TEXT NOT NULL,
          type TEXT NOT NULL,
          amount REAL DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS logs (
          id INTEGER PRIMARY KEY,
          service TEXT NOT NULL,
          level TEXT NOT NULL,
          status TEXT,
          message TEXT
        );
        CREATE TABLE IF NOT EXISTS requests (
          id INTEGER PRIMARY KEY,
          endpoint TEXT NOT NULL,
          method TEXT NOT NULL,
          duration_ms INTEGER,
          created_at TEXT
        );
      SQL
    end
  end
end
